/// Convert a `mzstd_bindings::MzstdError` error to a NAPI error.
///
/// The stable numeric error code is deliberately not interpolated into this message —
/// `napi::Error` has no per-variant subclass to attach it to. When available, it is exposed
/// as a structured `code` field on the `*Info` companion class instead (see
/// `gen_napi_error_class`), never smuggled into human-facing text.
#[allow(dead_code)]
fn mzstd_error_to_napi_err(e: mzstd_bindings::MzstdError) -> napi::Error {
    let mut error = napi::Error::new(napi::Status::GenericFailure, e.to_string());
    let (kind, error_code): (&str, u32) = match &e {
        mzstd_bindings::MzstdError::InvalidLevel { .. } => ("InvalidLevel", 2),
        mzstd_bindings::MzstdError::Compression(..) => ("Compression", 2),
        mzstd_bindings::MzstdError::Decompression(..) => ("Decompression", 2),
        mzstd_bindings::MzstdError::Dictionary(..) => ("Dictionary", 2),
        mzstd_bindings::MzstdError::InputTooLarge { .. } => ("InputTooLarge", 2),
        mzstd_bindings::MzstdError::StreamClosed => ("StreamClosed", 2),
        #[allow(unreachable_patterns)]
        _ => ("Unknown", 2),
    };
    let info = format!(
        "{{\"kind\":{},\"errorCode\":{}}}",
        serde_json::Value::String(kind.to_string()),
        error_code
    );
    error.set_cause(napi::Error::new(
        napi::Status::GenericFailure,
        format!("alef:error-info:{info}"),
    ));
    error
}

#[allow(dead_code)]
fn alef_napi_err<E: std::fmt::Display + 'static>(e: E) -> napi::Error {
    let message = e.to_string();
    let boxed: Box<dyn std::any::Any> = Box::new(e);
    let boxed = match boxed.downcast::<mzstd_bindings::MzstdError>() {
        Ok(typed) => return mzstd_error_to_napi_err(*typed),
        Err(other) => other,
    };
    drop(boxed);
    napi::Error::new(napi::Status::GenericFailure, message)
}
